200	    /**
201	     * The owner's age band derived from {@link #birthDate} relative to the
202	     * {@link #registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
203	     * and {@code 'SENIOR'} at 65 or older. Returns {@code null} when no birthDate is set. The age
204	     * is the number of complete years between the birthDate and the registrationDate (or the
205	     * current date when the registrationDate is not yet set).
206	     */
207	    public String getAgeBand() {
208	        if (this.birthDate == null) {
209	            return null;
210	        }
211	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
212	        int years = Period.between(this.birthDate, reference).getYears();
213	        if (years < 18) {
214	            return "MINOR";
215	        }
216	        if (years < 65) {
217	            return "ADULT";
218	        }
219	        return "SENIOR";
220	    }
