299	    /**
300	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
301	     */
302	    public String getDisplayName() {
303	        return this.getLastName() + ", " + this.getFirstName();
304	    }
305	
306	    /**
307	     * The canonical URL path of this owner: {@code '/api/owners/'} followed by the owner's
308	     * {@linkplain #getId() id}, e.g. {@code '/api/owners/1'}.
309	     */
310	    public String getSelfLink() {
311	        return "/api/owners/" + this.getId();
312	    }
313	
314	    /**
315	     * The owner's initials: the upper-cased first letters of firstName and lastName,
316	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
317	     */
318	    public String getInitials() {
319	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
320	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
321	    }
322	
323	    /**
324	     * The fixed length of the tail that every {@linkplain #getMemberId() memberId} carries after its
325	     * {@code <REGION>} prefix: the 2-digit fiscal-year code, the 8-character HASH8 and the single Luhn
326	     * check digit ({@code 2 + 8 + 1 = 11}). The region prefix is therefore everything in the memberId
327	     * (before any collision suffix) up to this trailing block, so the region and fiscal-year segments
328	     * are read back from the memberId rather than re-derived.
329	     */
330	    private static final int MEMBER_ID_TAIL = 11;
331	
332	    /**
333	     * The owner's base memberId, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
334	     * {@linkplain #getRegion() region} derived from the owner's postcode (or {@link #UNKNOWN_REGION}
335	     * when the postcode maps to no known region), the 2-digit {@linkplain #fiscalYearCode() fiscal-year
336	     * code} FY, the 8 upper-case hex HASH8 (the first 8 hex characters of the SHA-256 of the normalized
337	     * (E.164) telephone concatenated with the lastName, the same HASH8 the region-and-hash identity
338	     * uses), and a single Luhn {@linkplain #luhnCheckDigit(String) check digit} CHK computed over the
339	     * decimal digits of {@code <REGION><FY><HASH8>}, e.g. {@code 'NSW273C1A9F2B4'}. This is the single
340	     * source of the owner's identity; the stored {@linkplain #getMemberId() memberId} is this value
341	     * (with a collision suffix appended only when it clashes with an existing owner's), and the owner's
342	     * {@linkplain #getLocality() locality} and {@linkplain #getFiscalYear() fiscal year} are read back
343	     * from it.
344	     */
345	    public String computeMemberId() {
346	        String region = getRegion() != null ? getRegion() : UNKNOWN_REGION;
347	        String hash8 = HashUtils.sha256Hex(this.telephone + this.getLastName()).toUpperCase().substring(0, 8);
348	        String prefix = region + fiscalYearCode() + hash8;
349	        return prefix + luhnCheckDigit(prefix);
350	    }
351	
352	    /**
353	     * The {@linkplain #getMemberId() memberId} without its collision suffix: the memberId up to the
354	     * first {@code '-'} (the {@code '-<n>'} suffix appended only to de-duplicate a clashing id), or
355	     * {@code null} when the owner has no memberId. This is the {@code '<REGION><FY><HASH8><CHK>'} base
356	     * from which the {@linkplain #getLocality() locality} and {@linkplain #getFiscalYear() fiscal year}
357	     * are read.
358	     */
359	    private String memberIdBase() {
360	        if (this.memberId == null) {
361	            return null;
362	        }
363	        int dash = this.memberId.indexOf('-');
364	        return dash < 0 ? this.memberId : this.memberId.substring(0, dash);
365	    }
366	
367	    /**
368	     * The owner's fiscal year, formatted {@code 'FY<YY>'}, e.g. {@code 'FY27'}. The two YY digits are
369	     * read from the {@linkplain #getMemberId() memberId} (the {@code <FY>} segment embedded in it), so
370	     * the fiscal-year value shares the owner's single memberId identity; for an owner that has no
371	     * memberId the digits fall back to the {@linkplain #fiscalYearCode() fiscal-year code} of the
372	     * (business-day-adjusted) {@link #registrationDate}. The fiscal year starts on 1 July and is
373	     * labelled by the calendar year in which it ends.
374	     */
375	    public String getFiscalYear() {
376	        String base = memberIdBase();
377	        if (base != null && base.length() >= MEMBER_ID_TAIL) {
378	            return "FY" + base.substring(base.length() - MEMBER_ID_TAIL, base.length() - MEMBER_ID_TAIL + 2);
379	        }
380	        return "FY" + fiscalYearCode();
381	    }
382	
383	    /**
384	     * The two-digit fiscal-year code {@code '<YY>'}: the last two digits of the
385	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the (business-day-adjusted)
386	     * {@link #registrationDate}, zero-padded, e.g. {@code '27'}. This is the FY segment embedded in the
387	     * owner's {@linkplain #computeMemberId() memberId} at creation, and the fallback the
388	     * {@linkplain #getFiscalYear() fiscal year} reads when no memberId is present.
389	     */
390	    private String fiscalYearCode() {
391	        return String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
392	    }
393	
394	    /**
395	     * The fiscal year that contains the given date, identified by the calendar year in which it
396	     * ends. The fiscal year starts on 1 July, so a date in July through December belongs to the
397	     * fiscal year ending in the following calendar year, while a date in January through June
398	     * belongs to the fiscal year ending in the same calendar year.
399	     */
400	    private static int fiscalYearOf(LocalDate date) {
401	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
402	    }
403	
404	    /**
405	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
406	     * contained in {@code value}. Reading the digits right to left, every second one is
407	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
408	     * digits are summed, and the check digit is the amount that must be added to that sum to
409	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
410	     * the digit is taken over exactly the digits the string carries.
411	     */
412	    private static int luhnCheckDigit(String value) {
413	        int sum = 0;
414	        boolean doubling = true;
415	        for (int i = value.length() - 1; i >= 0; i--) {
416	            char c = value.charAt(i);
417	            if (c < '0' || c > '9') {
418	                continue;
419	            }
420	            int digit = c - '0';
421	            if (doubling) {
422	                digit *= 2;
423	                if (digit > 9) {
424	                    digit -= 9;
425	                }
426	            }
427	            sum += digit;
428	            doubling = !doubling;
429	        }
430	        return (10 - (sum % 10)) % 10;
431	    }
432	
433	    /** Fixed city-to-region table used to derive an owner's locality. */
434	    private static final Map<String, String> CITY_REGION = Map.of(
435	        "Sydney", "NSW",
436	        "Melbourne", "VIC",
437	        "Brisbane", "QLD");
438	
439	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
440	    public static final String UNKNOWN_REGION = "UNKNOWN";
441	
442	    /**
443	     * The canonical region for a city, derived from the fixed city-to-region table
444	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
445	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
446	     * source of the city-to-region mapping, shared by every rule that is keyed by
447	     * region so the mapping is never re-derived elsewhere.
448	     */
449	    public static String regionOf(String city) {
450	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
451	    }
452	
453	    /**
454	     * The owner's locality: the {@code <REGION>} component of the {@link #getMemberId() memberId} (its
455	     * prefix before the trailing {@code <FY><HASH8><CHK>} block), which is the region derived from the
456	     * owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no known region).
457	     * Locality is read from the memberId identity so it never re-derives a region of its own; it is
458	     * {@link #UNKNOWN_REGION} for an owner that has no memberId.
459	     */
460	    public String getLocality() {
461	        String base = memberIdBase();
462	        if (base == null || base.length() <= MEMBER_ID_TAIL) {
463	            return UNKNOWN_REGION;
464	        }
465	        return base.substring(0, base.length() - MEMBER_ID_TAIL);
466	    }
467	
468	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
469	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
470	        "NSW", "Australia/Sydney",
471	        "VIC", "Australia/Melbourne",
472	        "QLD", "Australia/Brisbane");
473	
474	    /**
475	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
476	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
477	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
478	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
479	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
480	     */
481	    public String getTimezone() {
482	        return REGION_TIMEZONE.get(getLocality());
483	    }
484	
485	    /**
486	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
487	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. TIER is
488	     * {@code 'PREMIUM'} when {@linkplain #getMembershipLevel() membershipLevel} is 3 or more,
489	     * otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's
490	     * {@linkplain #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
491	     * {@code 'REGIONAL'}. It reads the locality against the shared region table so it never
492	     * re-derives a region of its own.
493	     */
494	    public String getOwnerSegment() {
495	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
496	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
497	        return tier + "_" + area;
498	    }
499	
500	    /**
501	     * The region derived from this owner's postcode alone: the region whose fixed
502	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
503	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
504	     * component built into the owner's {@linkplain #computeMemberId() memberId} at creation and,
505	     * through it, the source of the owner's {@linkplain #getLocality() locality}. It is the single
506	     * place a region is read from an
507	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
508	     */
509	    public String getRegion() {
510	        return regionOfPostcode(this.postcode);
511	    }
512	
513	    /**
514	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
515	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
516	     * no known range.
517	     */
518	    private static String regionOfPostcode(String postcode) {
519	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
520	            return null;
521	        }
522	        int value = Integer.parseInt(postcode);
523	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
524	            int[] range = entry.getValue();
525	            if (value >= range[0] && value <= range[1]) {
526	                return entry.getKey();
527	            }
528	        }
529	        return null;
530	    }
531	
532	    /**
533	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
534	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
535	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
536	     */
537	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
538	        "NSW", new int[] {2000, 2099},
539	        "VIC", new int[] {3000, 3099},
540	        "QLD", new int[] {4000, 4099});
541	
542	    /**
543	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
544	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
545	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
546	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
547	     * city with no known region accepts any 4-digit postcode.
548	     */
549	    public boolean isPostcodeValid() {
550	        if (this.postcode == null) {
551	            return true;
552	        }
553	        if (!this.postcode.matches("[0-9]{4}")) {
554	            return false;
555	        }
556	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
557	        if (range == null) {
558	            return true;
559	        }
560	        int value = Integer.parseInt(this.postcode);
561	        return value >= range[0] && value <= range[1];
562	    }
563	
564	    /**
565	     * The national (subscriber) digit count required by each known country calling code, keyed by
566	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
567	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
568	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
569	     * re-derived elsewhere.
570	     */
571	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
572	        "1", 10,
573	        "61", 9);
574	
575	    /**
576	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
577	     * E.164 digit string, choosing the longest matching code known to
578	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
579	     * country code. This is the single place a country code is read from an E.164 number, so every
580	     * rule keyed by that code shares one derivation.
581	     */
582	    private static String countryCodeOf(String e164Digits) {
583	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
584	            .filter(e164Digits::startsWith)
585	            .max(Comparator.comparingInt(String::length))
586	            .orElse(null);
587	    }
588	
589	    /**
590	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
591	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
592	     * known code wins; a number whose country code is not recognised passes this check (its length is
593	     * then governed only by the general E.164 bound), while a recognised code must be followed by
594	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
595	     */
596	    public static boolean hasValidNationalLength(String e164Digits) {
597	        String countryCode = countryCodeOf(e164Digits);
598	        if (countryCode == null) {
599	            return true;
600	        }
601	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
602	    }
603	
604	    /**
605	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
606	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
607	     * gain 3 when the owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one
608	     * elapsed fiscal year. The email, namesake and household factors are available on creation; the
609	     * tenure factor is reached only once at least one fiscal-year boundary has passed.
610	     */
611	    public Integer getMembershipPoints() {
612	        int points = 0;
613	        if (hasEmail()) {
614	            points += 2;
615	        }
616	        if (hasNoNamesakes()) {
617	            points += 1;
618	        }
619	        if (hasLargeHousehold()) {
620	            points += 2;
621	        }
622	        if (hasQualifyingTenure()) {
623	            points += 3;
624	        }
625	        return points;
626	    }
627	
628	    /**
629	     * The owner's membership level, a number from 1 to 4. For an owner created through the
630	     * creation pipeline this is the value assigned and stored at creation time; an owner that
631	     * carries no assigned level (e.g. seed data, or an owner not created through that pipeline)
632	     * reports its {@linkplain #getBaseMembershipLevel() base level} derived from its
633	     * membershipPoints. This is the single value read by the API for an owner's membership level.
634	     */
635	    public Integer getMembershipLevel() {
636	        return this.membershipLevel != null ? this.membershipLevel : getBaseMembershipLevel();
637	    }
638	
639	    public void setMembershipLevel(Integer membershipLevel) {
640	        this.membershipLevel = membershipLevel;
641	    }
642	
643	    /**
644	     * The owner's base membership level, a number from 1 to 4 derived directly from
645	     * {@linkplain #getMembershipPoints() membershipPoints}: level 1 for 0-1 points, level 2 for 2-3,
646	     * level 3 for 4-5, and level 4 for 6 or more. This is the level the creation pipeline starts
647	     * from when it assigns the owner's stored {@linkplain #getMembershipLevel() membershipLevel}.
648	     */
649	    public Integer getBaseMembershipLevel() {
650	        int points = getMembershipPoints();
651	        if (points >= 6) {
652	            return 4;
653	        }
654	        if (points >= 4) {
655	            return 3;
656	        }
657	        if (points >= 2) {
658	            return 2;
659	        }
660	        return 1;
661	    }
662	
663	    /**
664	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
665	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
666	     * known, is treated as not a large household.
667	     */
668	    private boolean hasLargeHousehold() {
669	        return this.householdSize != null && this.householdSize >= 3;
670	    }
671	
672	    /**
673	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
674	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
675	     * email presence so the check is never re-derived elsewhere.
676	     */
677	    private boolean hasEmail() {
678	        return this.email != null && !this.email.isEmpty();
679	    }
680	
681	    /**
682	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
683	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
684	     * not known, is treated as not unique.
685	     */
686	    private boolean hasNoNamesakes() {
687	        return this.namesakeCount != null && this.namesakeCount == 0;
688	    }
689	
690	    /**
691	     * Whether this owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one elapsed
692	     * fiscal year. A newly created owner (zero elapsed fiscal years) does not qualify; the threshold
693	     * is crossed only once at least one fiscal-year boundary has passed since registration.
694	     */
695	    private boolean hasQualifyingTenure() {
696	        return this.getTenureFiscalYears() >= 1;
697	    }
698	
699	    /**
700	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
701	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
702	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
703	     * created owner has zero tenure). Never negative.
704	     */
705	    public long getTenureFiscalYears() {
706	        if (this.registrationDate == null) {
707	            return 0;
708	        }
709	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
710	    }
711	
712	    /**
713	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
714	     * otherwise {@code 'PHONE'}.
715	     */
716	    public String getContactPreference() {
717	        return hasEmail() ? "EMAIL" : "PHONE";
718	    }
719	
720	    /**
721	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
722	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
723	     * the national digits grouped into threes from the left separated by spaces,
724	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
725	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
726	     * E.164 form, or carries no known country code.
727	     */
728	    public String getTelephoneDisplay() {
729	        if (this.telephone == null || !this.telephone.startsWith("+")) {
730	            return this.telephone;
731	        }
732	        String digits = this.telephone.substring(1);
733	        String countryCode = countryCodeOf(digits);
734	        if (countryCode == null) {
735	            return this.telephone;
736	        }
737	        String national = digits.substring(countryCode.length());
738	        StringBuilder groups = new StringBuilder();
739	        for (int i = 0; i < national.length(); i += 3) {
740	            if (groups.length() > 0) {
741	                groups.append(' ');
742	            }
743	            groups.append(national, i, Math.min(i + 3, national.length()));
744	        }
745	        return "+" + countryCode + " " + groups;
746	    }
747	
748	    /**
749	     * The owner's identity key: the single derived value used for duplicate detection. It is the
750	     * lower-case hex SHA-256 (64 characters) of the normalized (E.164) telephone, the email
751	     * (already lower-cased, or the empty string when absent) and the {@linkplain #soundex(String)
752	     * soundex} of the lastName, joined with {@code '|'} before hashing, e.g. the digest of
753	     * {@code '+61412345678|jane@example.test|J500'}. Two owners are duplicates, and the second is
754	     * rejected with {@code 409}, only when their whole identity keys are equal.
755	     */
756	    public String getIdentityKey() {
757	        String telephonePart = this.telephone == null ? "" : this.telephone;
758	        String emailPart = this.email == null ? "" : this.email;
759	        String soundexPart = soundex(this.getLastName());
760	        return HashUtils.sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
761	    }
762	
763	    /**
764	     * The American Soundex code of {@code name}: its first letter followed by three digits encoding
765	     * the remaining consonant sounds ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2};
766	     * {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w,y}
767	     * are not coded). Adjacent letters with the same code, and same-coded letters separated only by
768	     * {@code h} or {@code w}, contribute a single digit; a vowel between two same-coded letters
769	     * keeps both. The result is right-padded with zeros and truncated to four characters. Non-letters
770	     * are ignored, and a {@code null} or letter-free name yields the empty string. Used to build the
771	     * owner's {@link #getIdentityKey() identity key} and to group households by surname sound.
772	     */
773	    public static String soundex(String name) {
774	        if (name == null) {
775	            return "";
776	        }
777	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
778	        if (letters.isEmpty()) {
779	            return "";
780	        }
781	        StringBuilder code = new StringBuilder();
782	        code.append(letters.charAt(0));
783	        char previous = soundexDigit(letters.charAt(0));
784	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
785	            char c = letters.charAt(i);
786	            char digit = soundexDigit(c);
787	            if (digit != '0' && digit != previous) {
788	                code.append(digit);
789	            }
790	            if (c != 'H' && c != 'W') {
791	                previous = digit;
792	            }
793	        }
794	        while (code.length() < 4) {
795	            code.append('0');
796	        }
797	        return code.toString();
798	    }
799	
800	    /**
801	     * The Soundex digit for a single upper-case letter (see {@link #soundex(String)}), or
802	     * {@code '0'} for a letter that is not coded (a vowel, or {@code h}, {@code w} or {@code y}).
803	     */
804	    private static char soundexDigit(char c) {
805	        switch (c) {
806	            case 'B': case 'F': case 'P': case 'V':
807	                return '1';
808	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
809	                return '2';
810	            case 'D': case 'T':
811	                return '3';
812	            case 'L':
813	                return '4';
814	            case 'M': case 'N':
815	                return '5';
816	            case 'R':
817	                return '6';
818	            default:
819	                return '0';
820	        }
821	    }
822	
823	    protected Set<Pet> getPetsInternal() {
824	        if (this.pets == null) {
825	            this.pets = new HashSet<>();
826	        }
827	        return this.pets;
828	    }
829	
830	    protected void setPetsInternal(Set<Pet> pets) {
831	        this.pets = pets;
832	    }
833	
834	    public List<Pet> getPets() {
835	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
836	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
837	        return Collections.unmodifiableList(sortedPets);
838	    }
839	
840	    public void setPets(List<Pet> pets) {
841	        this.pets = new HashSet<>(pets);
842	    }
843	
844	    public void addPet(Pet pet) {
845	        getPetsInternal().add(pet);
846	        pet.setOwner(this);
847	    }
848	
849	    /**
850	     * Return the Pet with the given name, or null if none found for this Owner.
851	     *
852	     * @param name to test
853	     * @return true if pet name is already in use
854	     */
855	    public Pet getPet(String name) {
856	        return getPet(name, false);
857	    }
858	
859	    /**
860	     * Return the Pet with the given name, or null if none found for this Owner.
861	     *
862	     * @param name to test
863	     * @return true if pet name is already in use
864	     */
865	    public Pet getPet(String name, boolean ignoreNew) {
866	        name = name.toLowerCase();
867	        for (Pet pet : getPetsInternal()) {
868	            if (!ignoreNew || !pet.isNew()) {
869	                String compName = pet.getName();
870	                compName = compName.toLowerCase();
871	                if (compName.equals(name)) {
872	                    return pet;
873	                }
874	            }
875	        }
876	        return null;
877	    }
878	
879	    public Pet getPet(Integer petId) {
880	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
881	    }
882	
883	    @Override
884	    public String toString() {
885	        return new ToStringCreator(this)
886	
887	            .append("id", this.getId())
888	            .append("new", this.isNew())
889	            .append("lastName", this.getLastName())
890	            .append("firstName", this.getFirstName())
891	            .append("address", this.address)
892	            .append("city", this.city)
893	            .append("telephone", this.telephone)
894	            .append("email", this.email)
895	            .toString();
896	    }
897	}
