117	    /**
118	     * The owner's salutation: the {@link #getTitle() title} and lastName separated by a single
119	     * space when a title is present, or just the lastName when no title was given.
120	     */
121	    public String getSalutation() {
122	        if (this.title == null || this.title.isEmpty()) {
123	            return this.getLastName();
