323	    /**
324	     * The fixed length of the tail that every {@linkplain #getMemberId() memberId} carries after its
325	     * {@code <REGION>} prefix: the 2-digit fiscal-year code, the 8-character HASH8 and the single Luhn
326	     * check digit ({@code 2 + 8 + 1 = 11}). The region prefix is therefore everything in the memberId
327	     * (before any collision suffix) up to this trailing block, so the region and fiscal-year segments
328	     * are read back from the memberId rather than re-derived.
329	     */
330	    private static final int MEMBER_ID_TAIL = 11;
331	
332	    /**
333	     * The owner's base memberId, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
334	     * {@linkplain #getRegion() region} derived from the owner's postcode (or {@link #UNKNOWN_REGION}
335	     * when the postcode maps to no known region), the 2-digit {@linkplain #fiscalYearCode() fiscal-year
336	     * code} FY, the 8 upper-case hex HASH8 (the first 8 hex characters of the SHA-256 of the normalized
337	     * (E.164) telephone concatenated with the lastName, the same HASH8 the region-and-hash identity
338	     * uses), and a single Luhn {@linkplain #luhnCheckDigit(String) check digit} CHK computed over the
339	     * decimal digits of {@code <REGION><FY><HASH8>}, e.g. {@code 'NSW273C1A9F2B4'}. This is the single
340	     * source of the owner's identity; the stored {@linkplain #getMemberId() memberId} is this value
341	     * (with a collision suffix appended only when it clashes with an existing owner's), and the owner's
342	     * {@linkplain #getLocality() locality} and {@linkplain #getFiscalYear() fiscal year} are read back
343	     * from it.
344	     */
345	    public String computeMemberId() {
346	        String region = getRegion() != null ? getRegion() : UNKNOWN_REGION;
347	        String hash8 = HashUtils.sha256Hex(this.telephone + this.getLastName()).toUpperCase().substring(0, 8);
348	        String prefix = region + fiscalYearCode() + hash8;
349	        return prefix + luhnCheckDigit(prefix);
350	    }
351	
352	    /**
353	     * The {@linkplain #getMemberId() memberId} without its collision suffix: the memberId up to the
354	     * first {@code '-'} (the {@code '-<n>'} suffix appended only to de-duplicate a clashing id), or
355	     * {@code null} when the owner has no memberId. This is the {@code '<REGION><FY><HASH8><CHK>'} base
356	     * from which the {@linkplain #getLocality() locality} and {@linkplain #getFiscalYear() fiscal year}
357	     * are read.
358	     */
359	    private String memberIdBase() {
360	        if (this.memberId == null) {
361	            return null;
362	        }
363	        int dash = this.memberId.indexOf('-');
364	        return dash < 0 ? this.memberId : this.memberId.substring(0, dash);
365	    }
366	
367	    /**
368	     * The owner's fiscal year, formatted {@code 'FY<YY>'}, e.g. {@code 'FY27'}. The two YY digits are
369	     * read from the {@linkplain #getMemberId() memberId} (the {@code <FY>} segment embedded in it), so
370	     * the fiscal-year value shares the owner's single memberId identity; for an owner that has no
371	     * memberId the digits fall back to the {@linkplain #fiscalYearCode() fiscal-year code} of the
372	     * (business-day-adjusted) {@link #registrationDate}. The fiscal year starts on 1 July and is
373	     * labelled by the calendar year in which it ends.
374	     */
375	    public String getFiscalYear() {
376	        String base = memberIdBase();
377	        if (base != null && base.length() >= MEMBER_ID_TAIL) {
378	            return "FY" + base.substring(base.length() - MEMBER_ID_TAIL, base.length() - MEMBER_ID_TAIL + 2);
379	        }
380	        return "FY" + fiscalYearCode();
381	    }
382	
383	    /**
384	     * The two-digit fiscal-year code {@code '<YY>'}: the last two digits of the
385	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the (business-day-adjusted)
386	     * {@link #registrationDate}, zero-padded, e.g. {@code '27'}. This is the FY segment embedded in the
387	     * owner's {@linkplain #computeMemberId() memberId} at creation, and the fallback the
388	     * {@linkplain #getFiscalYear() fiscal year} reads when no memberId is present.
389	     */
390	    private String fiscalYearCode() {
391	        return String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
392	    }
393	
394	    /**
395	     * The fiscal year that contains the given date, identified by the calendar year in which it
396	     * ends. The fiscal year starts on 1 July, so a date in July through December belongs to the
397	     * fiscal year ending in the following calendar year, while a date in January through June
398	     * belongs to the fiscal year ending in the same calendar year.
399	     */
400	    private static int fiscalYearOf(LocalDate date) {
401	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
402	    }
403	
404	    /**
405	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
406	     * contained in {@code value}. Reading the digits right to left, every second one is
407	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
408	     * digits are summed, and the check digit is the amount that must be added to that sum to
409	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
410	     * the digit is taken over exactly the digits the string carries.
411	     */
412	    private static int luhnCheckDigit(String value) {
413	        int sum = 0;
414	        boolean doubling = true;
415	        for (int i = value.length() - 1; i >= 0; i--) {
416	            char c = value.charAt(i);
417	            if (c < '0' || c > '9') {
418	                continue;
419	            }
420	            int digit = c - '0';
421	            if (doubling) {
422	                digit *= 2;
423	                if (digit > 9) {
424	                    digit -= 9;
425	                }
426	            }
427	            sum += digit;
428	            doubling = !doubling;
429	        }
430	        return (10 - (sum % 10)) % 10;
431	    }
