433	    /** Fixed city-to-region table used to derive an owner's locality. */
434	    private static final Map<String, String> CITY_REGION = Map.of(
435	        "Sydney", "NSW",
436	        "Melbourne", "VIC",
437	        "Brisbane", "QLD");
