513	    /**
514	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
515	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
516	     * no known range.
517	     */
518	    private static String regionOfPostcode(String postcode) {
519	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
520	            return null;
521	        }
522	        int value = Integer.parseInt(postcode);
523	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
524	            int[] range = entry.getValue();
525	            if (value >= range[0] && value <= range[1]) {
526	                return entry.getKey();
527	            }
528	        }
529	        return null;
530	    }
531	
532	    /**
533	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
534	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
535	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
536	     */
537	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
538	        "NSW", new int[] {2000, 2099},
539	        "VIC", new int[] {3000, 3099},
540	        "QLD", new int[] {4000, 4099});
541	
542	    /**
543	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
544	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
545	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
546	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
547	     * city with no known region accepts any 4-digit postcode.
548	     */
549	    public boolean isPostcodeValid() {
550	        if (this.postcode == null) {
551	            return true;
552	        }
553	        if (!this.postcode.matches("[0-9]{4}")) {
554	            return false;
555	        }
556	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
557	        if (range == null) {
558	            return true;
559	        }
560	        int value = Integer.parseInt(this.postcode);
561	        return value >= range[0] && value <= range[1];
562	    }
