564	    /**
565	     * The national (subscriber) digit count required by each known country calling code, keyed by
566	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
567	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
568	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
569	     * re-derived elsewhere.
570	     */
571	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
572	        "1", 10,
573	        "61", 9);
574	
575	    /**
576	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
577	     * E.164 digit string, choosing the longest matching code known to
578	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
579	     * country code. This is the single place a country code is read from an E.164 number, so every
580	     * rule keyed by that code shares one derivation.
581	     */
582	    private static String countryCodeOf(String e164Digits) {
583	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
584	            .filter(e164Digits::startsWith)
585	            .max(Comparator.comparingInt(String::length))
586	            .orElse(null);
587	    }
588	
589	    /**
590	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
591	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
592	     * known code wins; a number whose country code is not recognised passes this check (its length is
593	     * then governed only by the general E.164 bound), while a recognised code must be followed by
594	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
595	     */
596	    public static boolean hasValidNationalLength(String e164Digits) {
597	        String countryCode = countryCodeOf(e164Digits);
598	        if (countryCode == null) {
599	            return true;
600	        }
601	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
602	    }
