699	    /**
700	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
701	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
702	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
703	     * created owner has zero tenure). Never negative.
704	     */
705	    public long getTenureFiscalYears() {
706	        if (this.registrationDate == null) {
707	            return 0;
708	        }
709	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
710	    }
711	
712	    /**
713	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
714	     * otherwise {@code 'PHONE'}.
715	     */
716	    public String getContactPreference() {
717	        return hasEmail() ? "EMAIL" : "PHONE";
718	    }
719	
720	    /**
721	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
722	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
723	     * the national digits grouped into threes from the left separated by spaces,
724	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
725	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
726	     * E.164 form, or carries no known country code.
727	     */
728	    public String getTelephoneDisplay() {
729	        if (this.telephone == null || !this.telephone.startsWith("+")) {
730	            return this.telephone;
731	        }
732	        String digits = this.telephone.substring(1);
733	        String countryCode = countryCodeOf(digits);
734	        if (countryCode == null) {
735	            return this.telephone;
736	        }
737	        String national = digits.substring(countryCode.length());
738	        StringBuilder groups = new StringBuilder();
739	        for (int i = 0; i < national.length(); i += 3) {
740	            if (groups.length() > 0) {
741	                groups.append(' ');
742	            }
743	            groups.append(national, i, Math.min(i + 3, national.length()));
744	        }
745	        return "+" + countryCode + " " + groups;
746	    }
747	
748	    /**
749	     * The owner's identity key: the single derived value used for duplicate detection. It is the
750	     * lower-case hex SHA-256 (64 characters) of the normalized (E.164) telephone, the email
751	     * (already lower-cased, or the empty string when absent) and the {@linkplain #soundex(String)
752	     * soundex} of the lastName, joined with {@code '|'} before hashing, e.g. the digest of
753	     * {@code '+61412345678|jane@example.test|J500'}. Two owners are duplicates, and the second is
754	     * rejected with {@code 409}, only when their whole identity keys are equal.
755	     */
756	    public String getIdentityKey() {
757	        String telephonePart = this.telephone == null ? "" : this.telephone;
758	        String emailPart = this.email == null ? "" : this.email;
759	        String soundexPart = soundex(this.getLastName());
760	        return HashUtils.sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
761	    }
762	
763	    /**
764	     * The American Soundex code of {@code name}: its first letter followed by three digits encoding
765	     * the remaining consonant sounds ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2};
766	     * {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w,y}
767	     * are not coded). Adjacent letters with the same code, and same-coded letters separated only by
768	     * {@code h} or {@code w}, contribute a single digit; a vowel between two same-coded letters
769	     * keeps both. The result is right-padded with zeros and truncated to four characters. Non-letters
770	     * are ignored, and a {@code null} or letter-free name yields the empty string. Used to build the
771	     * owner's {@link #getIdentityKey() identity key} and to group households by surname sound.
772	     */
773	    public static String soundex(String name) {
774	        if (name == null) {
775	            return "";
776	        }
777	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
778	        if (letters.isEmpty()) {
779	            return "";
780	        }
781	        StringBuilder code = new StringBuilder();
782	        code.append(letters.charAt(0));
783	        char previous = soundexDigit(letters.charAt(0));
784	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
785	            char c = letters.charAt(i);
786	            char digit = soundexDigit(c);
787	            if (digit != '0' && digit != previous) {
788	                code.append(digit);
789	            }
790	            if (c != 'H' && c != 'W') {
791	                previous = digit;
792	            }
793	        }
794	        while (code.length() < 4) {
795	            code.append('0');
796	        }
797	        return code.toString();
798	    }
799	
800	    /**
801	     * The Soundex digit for a single upper-case letter (see {@link #soundex(String)}), or
802	     * {@code '0'} for a letter that is not coded (a vowel, or {@code h}, {@code w} or {@code y}).
803	     */
804	    private static char soundexDigit(char c) {
805	        switch (c) {
806	            case 'B': case 'F': case 'P': case 'V':
807	                return '1';
808	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
809	                return '2';
810	            case 'D': case 'T':
811	                return '3';
812	            case 'L':
813	                return '4';
814	            case 'M': case 'N':
815	                return '5';
816	            case 'R':
817	                return '6';
818	            default:
819	                return '0';
820	        }
821	    }
