864	     */
865	    public Pet getPet(String name, boolean ignoreNew) {
866	        name = name.toLowerCase();
867	        for (Pet pet : getPetsInternal()) {
868	            if (!ignoreNew || !pet.isNew()) {
869	                String compName = pet.getName();
870	                compName = compName.toLowerCase();
871	                if (compName.equals(name)) {
872	                    return pet;
873	                }
874	            }
875	        }
876	        return null;
