17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	
23	/**
24	 * Utility methods for the SHA-256 hashing used to derive owners' stable identity
25	 * values. Separate from the entity and controller classes so the single hashing
26	 * implementation can be shared by every rule that hashes owner data (the customer
27	 * code, the household id and the identity key) rather than being re-derived in each.
28	 *
29	 * @see org.springframework.samples.petclinic.model.Owner#getIdentityKey()
30	 */
31	public abstract class HashUtils {
32	
33	    /**
34	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as a lower-case
35	     * hexadecimal string (two hex characters per digest byte, so 64 characters in
36	     * all). This is the single place the hashing-and-hex-encoding is performed;
37	     * callers that need an upper-case rendering or a shorter opaque token upper-case
38	     * and/or take a prefix of the result.
39	     */
40	    public static String sha256Hex(String input) {
41	        try {
42	            byte[] digest = MessageDigest.getInstance("SHA-256")
43	                .digest(input.getBytes(StandardCharsets.UTF_8));
44	            StringBuilder sb = new StringBuilder(digest.length * 2);
45	            for (byte b : digest) {
46	                sb.append(String.format("%02x", b));
47	            }
48	            return sb.toString();
49	        }
50	        catch (NoSuchAlgorithmException e) {
51	            throw new IllegalStateException("SHA-256 not available", e);
52	        }
53	    }
54	
55	}
