300	    private HttpStatus normalizeAndValidate(Owner owner) {
301	        if (!normalizeAddress(owner)) {
302	            return HttpStatus.BAD_REQUEST;
303	        }
304	        String telephone = toE164(owner.getTelephone());
305	        if (telephone == null) {
306	            return HttpStatus.BAD_REQUEST;
307	        }
308	        owner.setTelephone(telephone);
309	        if (isDisposableEmail(owner.getEmail())) {
310	            return HttpStatus.BAD_REQUEST;
