312	        if (!owner.isPostcodeValid()) {
313	            return HttpStatus.BAD_REQUEST;
314	        }
315	        if (owner.getRegistrationDate() != null
316	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
