340	    private boolean normalizeAddress(Owner owner) {
341	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
342	        if (!line1.isEmpty()) {
343	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
344	            owner.setAddressLine1(line1);
